# TLS 1.3 Constants
TLS_VERSION = (0x03, 0x03)  # TLS 1.3
HANDSHAKE_TYPE_CLIENT_HELLO = 1
HANDSHAKE_TYPE_ENCRYPTED_EXTENSIONS = 8
HANDSHAKE_TYPE_CERTIFICATE = 11
HANDSHAKE_TYPE_CERTIFICATE_VERIFY = 13
