# Helper functions for TLS record layer
def create_tls_record(content_type, version, data):
    """Create a TLS record layer packet."""
    record = struct.pack('!BBH', content_type, version[0], version[1])
    record += struct.pack('!H', len(data))
    return record + data

def create_handshake_message(msg_type, data):
    """Create a TLS handshake message."""
    msg = struct.pack('!BBB', msg_type, (len(data) >> 16) & 0xff, (len(data) >> 8) & 0xff, len(data) & 0xff)
    return msg + data

def create_client_hello(early_data=False):
    """Create a minimal TLS 1.3 ClientHello with 0-RTT support."""
    # Generate random session ID and client random
    session_id = os.urandom(32)
    client_random = os.urandom(32)
    
    # Supported groups extension
    supported_groups = b'\x00\x17'  # x25519
    
    # Supported versions extension
    supported_versions = b'\x03\x03'  # TLS 1.3
    
    # PSK key exchange modes extension
    psk_key_exchange_modes = b'\x01'  # psk_dhe_ke
    
    # Early data extension
    early_data_ext = b''
    if early_data:
        early_data_ext = b'\x00\x00'  # Empty early data extension
    
    # Build extensions
    extensions = b''
    extensions += struct.pack('!HH', 0x000b, len(supported_groups)) + supported_groups
    extensions += struct.pack('!HH', 0x002b, len(supported_versions)) + supported_versions
    extensions += struct.pack('!HH', 0x002d, len(psk_key_exchange_modes)) + psk_key_exchange_modes
    if early_data:
        extensions += struct.pack('!HH', 0x0005, len(early_data_ext)) + early_data_ext
    
    # Build ClientHello
    client_hello = struct.pack('!B', 0x01)  # Legacy version
    client_hello += client_random
    client_hello += struct.pack('!B', len(session_id)) + session_id
    client_hello += struct.pack('!H', 0x0001)  # Cipher suites: TLS_AES_128_GCM_SHA256
    client_hello += struct.pack('!B', 0x01)  # Compression methods
    client_hello += struct.pack('!H', len(extensions)) + extensions
    
    return create_handshake_message(HANDSHAKE_TYPE_CLIENT_HELLO, client_hello)

def send_early_data(sock, data):
    """Send 0-RTT early data."""
    # Create EndOfEarlyData message
    end_of_early_data = create_handshake_message(HANDSHAKE_TYPE_END_OF_EARLY_DATA, b'')
    
    # Create ApplicationData with early data
